def shapes_of(I):
    H=len(I); W=len(I[0])
    cnt=Counter(v for r_ in I for v in r_)
    bg=cnt.most_common(1)[0][0]
    seen=[[False]*W for _ in range(H)]
    out=[]
    for r in range(H):
        for c in range(W):
            if I[r][c]!=bg and not seen[r][c]:
                # BFS
                st=[(r,c)]; comp=[(r,c)]; seen[r][c]=True
                while st:
                    a,b=st.pop()
                    for da,db in [(1,0),(-1,0),(0,1),(0,-1)]:
                        na,nb=a+da,b+db
                        if 0<=na<H and 0<=nb<W and I[na][nb]==I[r][c] and not seen[na][nb]:
                            seen[na][nb]=True; comp.append((na,nb)); st.append((na,nb))
                f=[[0]*max(b+1 for _,b in comp) for _ in range(max(a for a,_ in comp)+1)]
                for a,b in comp: f[a][b]=I[r][c]
                norm=None
                try:
                    n=tuple(tuple(row) for row in f)
                except: n=None
                m=(min(a for a,_ in comp), min(b for _,b in comp))
                # identify tetromino type: cells relative to min
                cells=[(a-m[0], b-m[1]) for a,b in comp]
                relset=set(cells)
                types={}
                def keyof(rel):
                    return tuple(sorted(rel)), frozenset(zip(*[(a,b) for a,b in rel]))
                k=keyof(cells)
                out.append({'color':I[r][c],'pos':m,'cells':sorted(cells),'n':len(comp)})
    return out
